__c = await sha(__c+"|"+__r.i+"|"+__r.s+"|"+__r.a+"|"+__r.v+"|"+__r.t); }
if(__c!==chain && window.KV_LOG) window.KV_LOG("root re-derived from frozen log","#e0c060");
chain = __c; window.KV_ROOT = chain; }catch(e){}
