  // ================= BOTTOM BAR FEED =================
  (function(){
    var PC={1:"#d94f4f",2:"#4f7fd9",3:"#4fd98a",4:"#d9c14f"};

    var strip=document.createElement("div");
    strip.style.cssText="visibility:hidden;position:fixed;left:270px;right:250px;bottom:6px;height:54px;z-index:59;background:rgba(20,16,12,.9);border:1px solid #4a3f30;border-radius:7px;overflow-y:auto;overflow-x:hidden;padding:6px 12px;font:13px/1.55 monospace;color:#f4e4c1;";
    document.body.appendChild(strip);

